public int lengthOfLongestSubstring(String s) {
    java.util.Map<Character, Integer> last = new java.util.HashMap<>();
    int res = 0, i = 0;
    for (int j = 0; j < s.length(); j++) {
        char c = s.charAt(j);
        if (last.containsKey(c) && last.get(c) >= i) i = last.get(c) + 1;
        last.put(c, j);
        res = Math.max(res, j - i + 1);
    }
    return res;
}

