public int trap(int[] h) {
    int l = 0, r = h.length - 1, leftMax = 0, rightMax = 0, res = 0;
    while (l < r) {
        leftMax = Math.max(leftMax, h[l]);
        rightMax = Math.max(rightMax, h[r]);
        if (h[l] < h[r]) res += leftMax - h[l++];
        else res += rightMax - h[r--];
    }
    return res;
}

