public ListNode mergeKLists(ListNode[] lists) {
    java.util.PriorityQueue<ListNode> pq = new java.util.PriorityQueue<>((x, y) -> x.val - y.val);
    for (ListNode n : lists) if (n != null) pq.offer(n);
    ListNode dummy = new ListNode(0), cur = dummy;
    while (!pq.isEmpty()) {
        ListNode n = pq.poll(); cur.next = n;
        if (n.next != null) pq.offer(n.next);
        cur = cur.next;
    }
    return dummy.next;
}
